  }

  const normalized = decodedValue.replaceAll("\\", "/");
  if (normalized.startsWith("/") || /^[A-Za-z]:\//.test(normalized)) {
    return null;
  }

  const candidates = [normalized];
  while (candidates.length > 0) {
