      } catch {
        // The original value was decoded successfully; later percent signs may be literal.
      }
    }
  }

  const segments = normalized
    .split("/")
    .filter((segment) => segment && segment !== ".");

  return segments.length > 0 ? segments.join("/") : null;
}

