export function normalizeStorageKey(value: string): string | null {
  let decodedValue: string;

  try {
    decodedValue = decodeURIComponent(value).replaceAll("\\", "/");
  } catch {
    return null;
  }

  if (decodedValue.startsWith("/") || /^[A-Za-z]:\//.test(decodedValue)) {
    return null;
  }

  const segments = decodedValue.split("/");
  if (segments.some((segment) => segment === "..")) {
    return null;
  }

  const normalized = segments
    .filter((segment) => segment && segment !== ".")
    .join("/");

  return normalized || null;
}

let decodedValue: string;

try {
  decodedValue = decodeURIComponent(value);
} catch {
  return null;
}

let probe = decodedValue;
while (true) {
  const normalizedProbe = probe.replaceAll("\\", "/");
  if (
    normalizedProbe.startsWith("/") ||
    /^[A-Za-z]:\//.test(normalizedProbe) ||
    normalizedProbe.split("/").some((segment) => segment === "..")
  ) {
    return null;
  }

  if (!/%[0-9a-f]{2}/i.test(probe)) {
    break;
  }

  try {
    const nextProbe = decodeURIComponent(probe);
    if (nextProbe === probe) {
      break;
    }
    probe = nextProbe;
  } catch {
    break;
  }
}

const normalized = decodedValue
  .replaceAll("\\", "/")
  .split("/")
  .filter((segment) => segment && segment !== ".")
  .join("/");

return normalized || null;

